# Parameter-shapes voor peildatum met een waardelijst.
ex:PeilDatumPickList
    a sh:NodeShape ;
    sh:targetClass ex:PeilDatumPickList ;
    rdfs:label "Peildatum met een keuzelijst";
    rdfs:comment "Een shape voor het creeren van een keuzelijstveld waarmee de gebruiker de peildatum kan specificeren."@nl ;
    sh:property [
          sh:path ex:peildatum ;
          sh:name "peildatum";
          sh:description "Keuzelijst van peildatumwaarden."@nl ;
          sh:maxCount 1 ;
          sh:minCount 1 ;
          sh:datatype xsd:date ;
          sh:in ( 
                "2024-01-01"^^xsd:date 
                "2024-04-01"^^xsd:date 
                "2024-07-01"^^xsd:date 
                "2024-10-01"^^xsd:date 
                "2025-01-01"^^xsd:date 
                "2025-04-01"^^xsd:date 
                "2025-07-01"^^xsd:date 
                "2025-10-01"^^xsd:date
                "2026-01-01"^^xsd:date 
                "2026-04-01"^^xsd:date 
                "2026-07-01"^^xsd:date 
                "2026-10-01"^^xsd:date 
            )

      ]
.

