          }
        }
        BIND(IF(BOUND(?saldo_bedrag), ?saldo_bedrag, 0) AS ?bedrag_rubriek)
      }
    }

    # saldoNa
    {
      SELECT (SUM(?bedrag_rubriek) AS ?saldoNa)
      WHERE {        
        {
          SELECT ?rubriek ?saldo_datum ?saldo_bedrag
          WHERE {
            # BIND("2024-12-31"^^xsd:date AS ?eindperiode)
            ?rubriek a onz-fin:Grootboekrubriek ;
                    onz-g:isAbout ?saldo .
            ?saldo a onz-fin:EindSaldo ;
                  onz-fin:heeftGeldBedrag ?saldo_bedrag ;
                  onz-g:hasDate ?saldo_datum .
            FILTER (STRSTARTS(STRAFTER(STR(?rubriek), STR(onz-fin:)), "07"))
            FILTER (?saldo_datum <= ?eindperiode)
            FILTER NOT EXISTS {
              ?rubriek onz-g:isAbout ?otherSaldo .
