                          onz-g:hasDate ?otherDate .
              FILTER(?otherDate <= ?eindperiode && ?otherDate > ?saldo_datum)
            }
          }
        }
        BIND(IF(BOUND(?saldo_bedrag), ?saldo_bedrag, 0) AS ?bedrag_rubriek)
      }
    }

    # aflossing berekenen
    BIND(?saldoVoor - ?saldoNa AS ?aflossing)
    }
  }

}
