title: 22.1 Groei - wat is de omzetgroei?
weight: 22
---
## Concepten
- [Grootboekpost](http://purl.org/ozo/onz-fin#Grootboekpost)
- [Grootboekrubriek](http://purl.org/ozo/onz-fin#Grootboekrubriek)
## Relaties
- [deel van](http://purl.org/ozo/onz-g#partOf)
## Eigenschappen
- [heeft datum](http://purl.org/ozo/onz-g#hasDate)
- [heeftGeldBedrag](http://purl.org/ozo/onz-fin#heeftGeldBedrag)
## SPARQL query
```
# Indicator: Zorgkantoren 22.1 
# Parameters: ?startperiode, ?eindperiode
# Ontologie: versie 3.0.0 of nieuwer

PREFIX onz-fin: <http://purl.org/ozo/onz-fin#>
PREFIX onz-g:   <http://purl.org/ozo/onz-g#>
PREFIX xsd:     <http://www.w3.org/2001/XMLSchema#>

SELECT ?Kental ?Waarde
WHERE {
  {
    # Bereken verslagjaar en vergelijkingsjaar
    SELECT ?p_verslagjaar ?p_vergelijkingsjaar
    WHERE {
      # ========= Verslagjaar =========
      {
        SELECT (SUM(?p_bedrag) AS ?p_verslagjaar)
        WHERE {
            # BIND("2024-01-01"^^xsd:date AS ?startperiode)
            # BIND("2024-12-31"^^xsd:date AS ?eindperiode)
          {
            SELECT DISTINCT ?rubriek WHERE {
              ?rubriek a onz-fin:Grootboekrubriek .
              FILTER(STRSTARTS(STR(?rubriek), STR(onz-fin:)))
              FILTER(REGEX(STRAFTER(STR(?rubriek), STR(onz-fin:)), "^[0-9]{6}$"))
            }
          }
          BIND(STRAFTER(STR(?rubriek), STR(onz-fin:)) AS ?rubriekCode)

          ?grootboek_post a onz-fin:Grootboekpost ;
                          onz-g:partOf ?rubriek ;
                          onz-g:hasDate ?datum ;
                          onz-fin:heeftGeldBedrag ?geld_bedrag .

          FILTER (?datum >= ?startperiode && ?datum <= ?eindperiode)

          BIND(
            IF(
              STRSTARTS(?rubriekCode, "81") ||
              STRSTARTS(?rubriekCode, "82") ||
              STRSTARTS(?rubriekCode, "83") ||
              STRSTARTS(?rubriekCode, "89") ||
              STRSTARTS(?rubriekCode, "919") ||
              STRSTARTS(?rubriekCode, "920") ||
              STRSTARTS(?rubriekCode, "930"),
              ?geld_bedrag, 0
            ) AS ?p_bedrag
          )
        }
      }

      # ========= Vergelijkingsjaar =========
      {
        SELECT (SUM(?p_bedrag) AS ?p_vergelijkingsjaar)
        WHERE {
                # BIND("2024-01-01"^^xsd:date AS ?startperiode)
                # BIND("2024-12-31"^^xsd:date AS ?eindperiode)
          {
            SELECT DISTINCT ?rubriek WHERE {
              ?rubriek a onz-fin:Grootboekrubriek .
              FILTER(STRSTARTS(STR(?rubriek), STR(onz-fin:)))
              FILTER(REGEX(STRAFTER(STR(?rubriek), STR(onz-fin:)), "^[0-9]{6}$"))
            }
          }
          BIND(STRAFTER(STR(?rubriek), STR(onz-fin:)) AS ?rubriekCode)

          ?grootboek_post a onz-fin:Grootboekpost ;
                          onz-g:partOf ?rubriek ;
                          onz-g:hasDate ?datum ;
                          onz-fin:heeftGeldBedrag ?geld_bedrag .

            # vergelijkingsperiode = meetperiode minus 1 jaar
            BIND(xsd:date(CONCAT(STR(YEAR(?startperiode)-1), "-", 
                                 SUBSTR(STR(?startperiode), 6, 2), "-", 
                                 SUBSTR(STR(?startperiode), 9, 2))) AS ?startVergelijkingsperiode)

            BIND(xsd:date(CONCAT(STR(YEAR(?eindperiode)-1), "-", 
                                 SUBSTR(STR(?eindperiode), 6, 2), "-", 
                                 SUBSTR(STR(?eindperiode), 9, 2))) AS ?eindVergelijkingsperiode)

            FILTER (?datum >= ?startVergelijkingsperiode && ?datum <= ?eindVergelijkingsperiode)

          BIND(
            IF(
              STRSTARTS(?rubriekCode, "81") ||
              STRSTARTS(?rubriekCode, "82") ||
              STRSTARTS(?rubriekCode, "83") ||
              STRSTARTS(?rubriekCode, "89") ||
              STRSTARTS(?rubriekCode, "919") ||
              STRSTARTS(?rubriekCode, "920") ||
              STRSTARTS(?rubriekCode, "930"),
              ?geld_bedrag, 0
            ) AS ?p_bedrag
          )
        }
      }
    }
  }

  # Nu bereken omzetgroei
  BIND(
    IF(?p_vergelijkingsjaar = 0,
       "Ongedefinieerd"^^xsd:string,
       xsd:decimal(?p_verslagjaar / ?p_vergelijkingsjaar)
    ) AS ?omzetgroei
  )

  VALUES ?Kental { "Omzetgroei" "Omzetgroei%" }

  BIND(
    IF(?Kental = "Omzetgroei",
       ?omzetgroei,
       IF(DATATYPE(?omzetgroei) = xsd:string,
          "Ongedefinieerd"^^xsd:string,
          ?omzetgroei * 100
       )
    ) AS ?Waarde
  )
}
ORDER BY ?Kental

