prefix onz-zorg:  <http://purl.org/ozo/onz-zorg#>
PREFIX onz-g: <http://purl.org/ozo/onz-g#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?Kental ?Waarde
WHERE {
    {
        SELECT (IF(SUM(IF(?jaarrekeningpost = "A.III Financiële vaste activa", ?bedrag, 0)) = 0,
                "Ongedefinieerd"^^xsd:string,(SUM(IF(?jaarrekeningpost = "F Langlopende schulden", ?bedrag, 0)) / 
                SUM(IF(?jaarrekeningpost = "A.III Financiële vaste activa", ?bedrag, 0)))) AS ?ltv)
        WHERE {
